# Плохо: любой заказ по id
@order = Order.find(params[:id])

# Хорошо: только заказы текущего пользователя
@order = Current.user.orders.find(params[:id])

class OrderPolicy < ApplicationPolicy
  def update? = user.admin? || (record.user == user && record.pending?)

  class Scope < Scope
    def resolve = user.admin? ? scope.all : scope.where(user:)
  end
end

class OrdersController < ApplicationController
  def update
    @order = Order.find(params[:id])
    authorize @order                      # Pundit::NotAuthorizedError, если нельзя
    @order.update!(order_params)
  end

  def index
    @orders = policy_scope(Order)
  end
end
